    const ix = E.gridIdx, cur = typeof ix === "number" && ix >= 0 && Math.abs((g.sizes[ix] ?? NaN) - E.gridPitch) < 1e-9 ? ix : g.sizes.findIndex((s) => Math.abs(s - E.gridPitch) < 1e-9);
