// pcbdialogs/update-pcb — Tools > Update PCB from Schematic… (F8, DIALOG_UPDATE_PCB).
//
// The netlist is computed in the browser from the project's schematic sheets in their current state
// (canvas/pcb-netlist.ts, the hierarchy walked from the root sheet), the changes are listed as a dry run the
// way BOARD_NETLIST_UPDATER reports them, and Update PCB applies them as one undoable edit.
// New footprints come from the footprint library service (GET /api/libs/footprints/{lib}/{name}) when the
// server has one; without it the report says the footprint cannot be added.
import { E } from "../state";
import { SEXPR_BOARD_FILE_VERSION } from "../../canvas/format-version";
import { state } from "../appstore";
import type { Netlist, SheetFile, UpdateOptions, UpdatePlan } from "../../canvas/pcb-netlist";
import { liveDocument, projectDocs, type ProjectDocInfo } from "../projectfile";
import { NL } from "./canvas";
import { topLevelSheetsOf } from "../bootpick";
import { box, checkField, confirmBox, h, messageBox, openDialog, reportPanel, type Field } from "./ui";
import { store } from "../appstore";
import { messageText } from "../../../../shared/units";
import { applyNetlistChains, netlistChainsOf } from "../netchains";
import { applyDesignBlockLayoutsToGroups } from "./multichannel";

interface SchModuleInternals { _?: { symbolPins(doc: KDoc, item: KItem): { x: number; y: number; number: string; name: string; type: string; hidden: boolean }[]; isPowerSymbol(doc: KDoc, libId: string): boolean } }
const SCH_IU = 10000;

function rootSchematicOf(docs: ProjectDocInfo[]): ProjectDocInfo | null {
  const sch = docs.filter((d) => d.docType === "kicad_sch"); if (!sch.length) return null;
  const pro = docs.find((d) => d.docType === "kicad_pro");
  const stem = (p: string): string => p.replace(/\.[^./]+$/, "");
  const board = docs.find((d) => d.docId === state.docId);
  return (pro && sch.find((d) => stem(d.path) === stem(pro.path))) || (board && sch.find((d) => stem(d.path) === stem(board.path)))
    || sch.slice().sort((a, b) => a.path.split("/").length - b.path.split("/").length || a.path.length - b.path.length)[0];
}

/** Every schematic sheet of the project as it is now, and the netlist of the hierarchy under the root sheet. */
export async function projectNetlist(): Promise<{ netlist: Netlist; root: string; files: Map<string, SheetFile>; chainsPath: string; pro: Record<string, unknown> | null } | { error: string }> {
  const docs = projectDocs(), root = rootSchematicOf(docs);
  if (!root) return { error: "This project has no schematic." };
  const sch = (CollabTools.sch as (SchToolModule & SchModuleInternals) | undefined);
  const helpers = sch && sch._;
  if (!helpers || !helpers.symbolPins) return { error: "The schematic tools are not loaded." };
  const files = new Map<string, SheetFile>();
  await Promise.all(docs.filter((d) => d.docType === "kicad_sch").map(async (d) => {
    try {
      const live = await liveDocument(d.docId);
      const doc = KiCadCanvas.parseDoc(live.file, "kicad_sch");
      for (const op of live.ops) for (const c of op.changes || []) { try { KiCadCanvas.applyChange(doc, c, SCH_IU); } catch (e) { /* an op this reader cannot take */ } }
      const m = /\(uuid\s+"?([0-9a-fA-F-]{36})"?\s*\)/.exec(live.file.slice(0, 4000));
      files.set(d.path, { doc, uuid: m ? m[1] : "", file: d.path });
    } catch (e) { /* reported below as a missing sheet */ }
  }));
  // SCHEMATIC::GetTopLevelSheets: a KiCad 10 project may list several top-level sheets in its project file
  let pro: unknown = null;
  try {
    const proDoc = docs.find((d) => d.docType === "kicad_pro");
    const text = E.proSettings || (proDoc ? await fetch(`/api/docs/${proDoc.docId}/content`).then((r) => (r.ok ? r.text() : "")) : "");
    pro = text ? JSON.parse(text) : null;
  } catch (e) { pro = null; }
  const tops = topLevelSheetsOf(pro, docs, docs).map((t) => ({ sheet: files.get(t.doc.path) as SheetFile, name: t.name, uuid: t.uuid, path: t.doc.path })).filter((t) => !!t.sheet);
  const rootFile = tops.length > 1 ? tops[0].sheet : files.get(root.path);
  if (!rootFile) return { error: "The root schematic could not be read." };
  const resolve = (file: string, parent: SheetFile): SheetFile | null => {
    const dir = parent.file.split("/").slice(0, -1);
    const parts = [...dir, ...file.split("/")].filter((p) => p && p !== ".");
    const out: string[] = []; for (const p of parts) { if (p === "..") out.pop(); else out.push(p); }
    return files.get(out.join("/")) || files.get(file) || null;
  };
  const netlist = NL().buildNetlist(tops.length > 1 ? tops : rootFile, resolve, { symbolPins: helpers.symbolPins, isPower: (d, it) => helpers.isPowerSymbol(d, String(((KiCadCanvas.kid(it.node, "lib_id") as SNode | null) || [])[1])) }, root.path.split("/").pop()!.replace(/\.kicad_sch$/, ""), NL().netlistOptions(pro));
  // the net chains live in the first top-level sheet (SCHEMATIC::GetTopLevelSheet( 0 ))
  return { netlist, root: tops.length > 1 ? tops[0].path : root.path, files, chainsPath: tops.length ? tops[0].path : root.path, pro: pro && typeof pro === "object" ? pro as Record<string, unknown> : null };
}

// ---------------------------------------------------------------- the footprint library (optional service)
const libCache = new Map<string, SNode | "missing" | null>();
let libAvailable: boolean | null = null;
/** Fetch the library footprints a plan may need; null entries mean "no library service". */
async function fetchFootprints(fpids: string[]): Promise<void> {
  await Promise.all(fpids.filter((id) => !libCache.has(id)).map(async (fpid) => {
    const i = fpid.indexOf(":"); if (i <= 0) { libCache.set(fpid, "missing"); return; }
    if (libAvailable === false) { libCache.set(fpid, null); return; }
    try {
      const r = await fetch(`/api/libs/footprints/${encodeURIComponent(fpid.slice(0, i))}/${encodeURIComponent(fpid.slice(i + 1))}`, { headers: { accept: "application/json" } });
      const json = r.ok && /json/.test(r.headers.get("content-type") || "") ? (await r.json()) as { footprint?: string } : null;
      if (json && typeof json.footprint === "string") { libAvailable = true; const node = KiCadCanvas.parse(json.footprint); libCache.set(fpid, node || "missing"); }
      else if (r.status === 404 && libAvailable) libCache.set(fpid, "missing");
      else if (r.status === 404) {
        // a 404 is either "no such footprint" or "no such route": the library index tells the two apart
        if (libAvailable === null) { try { const p = await fetch("/api/libs/footprints", { headers: { accept: "application/json" } }); libAvailable = p.ok && /json/.test(p.headers.get("content-type") || ""); } catch (e) { libAvailable = false; } }
        libCache.set(fpid, libAvailable ? "missing" : null);
      } else libCache.set(fpid, null);
    } catch (e) { libCache.set(fpid, null); }
  }));
}

function boardFootprintIds(doc: KDoc): Set<string> {
  const out = new Set<string>();
  for (const it of doc.items.values()) if (it.kind === "footprint") out.add(String(it.node[1]));
  return out;
}

/** The plan as collaboration changes: one undo step. */
function planChanges(doc: KDoc, plan: UpdatePlan, addedIds?: string[]): KChange[] {
  const changes: KChange[] = [];
  for (const id of plan.removed) { const it = doc.items.get(id); if (it) changes.push(KiCadCanvas.removeChange(it)); }
  for (const [id, node] of plan.modified) { const it = doc.items.get(id); if (it) changes.push(KiCadCanvas.replaceChange(doc, { ...it, node })); }
  for (const node of plan.added) { const it = KiCadCanvas.createItem(doc, node); if (it) { changes.push(KiCadCanvas.addChange(doc, it)); if (addedIds && it.kind === "footprint") addedIds.push(it.id); } }
  return changes;
}

const OPTIONS: { key: keyof UpdateOptions; group: number; label: string; tip?: string; def: boolean }[] = [
  { key: "relinkByRef", group: 0, label: "Re-link footprints to schematic symbols based on their reference designators", def: false,
    tip: "Normally footprints are linked to their symbols via their Unique IDs.  Select this option only if you want to reset the footprint linkages based on their reference designators." },
  { key: "transferGroups", group: 0, label: "Group footprints based on symbol group", def: false },
  { key: "applyDesignBlockLayouts", group: 0, label: "Apply design block layouts to new groups", def: false,
    tip: "For each new group created from a design block, apply the block's saved footprint placement and routing automatically." },
  { key: "replaceFootprints", group: 1, label: "Replace footprints with those specified by symbols", def: true,
    tip: "Normally footprints on the board should be changed to match footprint assignment changes made in the schematic. Uncheck this only if you don't want to change existing footprints on the board." },
  { key: "deleteUnused", group: 1, label: "Delete footprints with no symbols", def: false, tip: "Remove from the board unlocked footprints which are not linked to a schematic symbol." },
  { key: "overrideLocks", group: 1, label: "Override locks", def: false },
  { key: "updateFields", group: 2, label: "Update footprint fields from symbols", def: true },
  { key: "removeExtraFields", group: 2, label: "Remove footprint fields not found in symbols", def: false }];
// DIALOG_SHIM::finishDialogSettings: the check boxes are kept between sessions
const REMEMBER_KEY = "kc.updatePcb.options";
const remembered: Partial<Record<keyof UpdateOptions, boolean>> = ((): Partial<Record<keyof UpdateOptions, boolean>> => {
  try { const v = JSON.parse(localStorage.getItem(REMEMBER_KEY) || "{}") as Record<string, unknown>; return v && typeof v === "object" ? v as Partial<Record<keyof UpdateOptions, boolean>> : {}; } catch (e) { return {}; }
})();
function remember(key: keyof UpdateOptions, v: boolean): void { remembered[key] = v; try { localStorage.setItem(REMEMBER_KEY, JSON.stringify(remembered)); } catch (e) { /* private window: kept for this session */ } }
/** BOARD_DESIGN_SETTINGS' Fab-layer text defaults (StyleFromSettings for the fields the update adds). */
function fabTextStyle(): { size: number; sizeV: number; thick: number; italic: boolean; upright: boolean } {
  const out = { size: 1, sizeV: 1, thick: 0.15, italic: false, upright: false };
  try {
    const pro = JSON.parse((E.proSettings as string | null) || "{}") as { board?: { design_settings?: { defaults?: Record<string, unknown> } } };
    const d = (pro.board && pro.board.design_settings && pro.board.design_settings.defaults) || {};
    const n = (k: string, def: number): number => (typeof d[k] === "number" && (d[k] as number) > 0 ? d[k] as number : def);
    out.size = n("fab_text_size_h", 1); out.sizeV = n("fab_text_size_v", 1); out.thick = n("fab_text_thickness", 0.15);
    out.italic = d.fab_text_italic === true; out.upright = d.fab_text_upright === true;
  } catch (e) { /* the defaults */ }
  return out;
}
const UPDATE_ANNOTATE_MSG = "Updating PCB requires a fully annotated schematic.";
/**
 * FetchNetlistFromSchematic( netlist, "Updating PCB requires a fully annotated schematic." ): the schematic's
 * ReadyToNetlist first.  An unannotated schematic is refused with that error; "No" to the duplicate sheet names
 * question stops silently.  From the schematic editor the Annotate dialog is offered first (ModalAnnotate).
 */
async function schematicReady(annotate: boolean): Promise<boolean> {
  const { readyToNetlist } = await import("../export-netlist");
  const st = { cancelled: false };
  if (await readyToNetlist(UPDATE_ANNOTATE_MSG, { annotate, state: st })) return true;
  if (!st.cancelled) messageBox("Error", UPDATE_ANNOTATE_MSG);
  return false;
}

export async function openUpdatePcb(ctx: ToolCtx): Promise<void> {
  const doc = E.kdoc as KDoc | null;
  if (!doc || doc.type !== "pcb") { ctx.toast("Update PCB from Schematic needs a board"); return; }
  if (!(await schematicReady(false))) return;
  // m_messagePanel: "Changes to Be Applied", saved as report.txt
  const report = reportPanel("260px", { fileName: "report.txt" });
  const reportBox = box("Changes to Be Applied", report.el);
  const fields = new Map<keyof UpdateOptions, Field<boolean>>();
  let netlist: Netlist | null = null, plan: UpdatePlan | null = null, busy = false, okBtn: HTMLButtonElement | null = null;
  let chains: ReturnType<typeof netlistChainsOf> = [];
  // PCB_EDIT_FRAME::OnNetlistChanged selects the new footprints and ~DIALOG_UPDATE_PCB starts the move tool with
  // them (m_runDragCommand): closing the dialog hands them to the cursor for placing
  const newFootprints: string[] = [];
  const vp = (store.get() as { viewport?: { units?: Parameters<typeof messageText>[1] } }).viewport || {};
  const options = (): UpdateOptions => {
    const st = fabTextStyle();
    const o: UpdateOptions = { newUuid: () => KiCadCanvas.newUuid(), footprintFor: (fpid) => { const v = libCache.get(fpid); return v && v !== "missing" ? NL().footprintFromLibrary(v, fpid, () => KiCadCanvas.newUuid()) : v === undefined ? null : v; },
      fieldSize: st.size, fieldSizeV: st.sizeV, fieldThickness: st.thick, fieldItalic: st.italic, fieldUpright: st.upright, formatLength: (mm) => messageText(mm, vp.units || "mm", "pcb") };
    for (const [k, f] of fields) (o as Record<string, unknown>)[k] = f.get();
    return o;
  };
  const dryRun = async (): Promise<void> => {
    if (!netlist || busy) return;
    busy = true;
    try {
      const have = boardFootprintIds(doc);
      const wanted = Array.from(new Set(netlist.components.map((c) => c.footprint).filter((f) => f && !have.has(f))));
      const toLoad = wanted.filter((f) => !libCache.has(f)).length;
      if (toLoad) report.set([{ severity: "info", text: `Loading ${toLoad} footprint${toLoad === 1 ? "" : "s"} from the libraries…`, busy: true }]);
      await fetchFootprints(wanted);
      // planned against a copy of nothing: planUpdate reads the document and returns new nodes
      plan = NL().planUpdate(doc, netlist, options());
      report.set(plan.report);
      if (okBtn && !E.viewOnly) okBtn.disabled = false;
    } finally { busy = false; }
  };
  const dlg = openDialog({ title: "Update PCB from Schematic", width: 760, okLabel: "Update PCB", cancelLabel: "Close", readOnly: !!E.viewOnly, noEnter: true,
    build(body) {
      const groups = [box("Options"), box("Update Footprints"), box("Update Fields")];
      for (const o of OPTIONS) {
        const f = checkField(remembered[o.key] ?? o.def, o.label, { key: String(o.key), tip: o.tip, ro: !!E.viewOnly, onChange: (v) => { remember(o.key, v); void dryRun(); } });
        fields.set(o.key, f); groups[o.group].append(f.el);
      }
      // OnOptionChanged: the design block layouts only with the groups transferred
      const tg = fields.get("transferGroups") as Field<boolean>, db = fields.get("applyDesignBlockLayouts") as Field<boolean>;
      const syncDb = (): void => { if (!tg.get()) { db.set(false); remember("applyDesignBlockLayouts", false); } db.input.disabled = !!E.viewOnly || !tg.get(); db.el.classList.toggle("disabled", db.input.disabled); };
      tg.input.addEventListener("change", syncDb); syncDb();
      body.append(groups[0], h("div", { class: "pd-cols2" }, groups[1], groups[2]), reportBox);
      report.set([{ severity: "info", text: "Reading the schematic…", busy: true }]);
    },
    ok() {
      if (!plan || E.viewOnly || !netlist) return false;
      // OnUpdateClick: the panel is relabelled and the updater runs again with the dry run off; its report replaces the
      // dry run's.  PerformUpdate( false ) deactivates the tool and clears the selection first.
      reportBox.firstElementChild!.textContent = "Changes Applied to PCB";
      if (E.tool !== "select") void import("../tools").then((T) => T.setTool("select"));
      (ctx as unknown as { setSelection?(ids: string[]): void }).setSelection?.([]);
      const P = (window as unknown as { PcbTools?: { applySelection?(c: ToolCtx, ids: string[]): void } }).PcbTools; if (P && P.applySelection) P.applySelection(ctx, []);
      const real = NL().planUpdate(doc, netlist, { ...options(), applied: true });
      // OnNetlistChanged: SpreadFootprints( new footprints, { 0, 0 }, true ) before they are handed to Move
      const fresh = real.added.filter((n) => n[0] === "footprint");
      const pt = (window as unknown as { PcbTools?: { packNodes?(d: { items: Map<string, KItem> }, ids: string[], o: { target: [number, number]; groupBySheet: boolean }): Map<string, SNode> } }).PcbTools;
      if (fresh.length && pt && pt.packNodes) {
        const items = new Map<string, KItem>();
        for (const n of fresh) { const it = KiCadCanvas.createItem(doc, n); if (it) items.set(it.id, it); }
        const packed = pt.packNodes({ items }, Array.from(items.keys()), { target: [0, 0], groupBySheet: true });
        for (const n of fresh) { const id = String(((KiCadCanvas.kid(n, "uuid") as SNode | null) || [])[1]); const p = packed.get(id); if (p) { n.length = 0; n.push(...p); } }
      }
      const added: string[] = [];
      const changes = planChanges(doc, real, added);
      if (changes.length) { newFootprints.splice(0, newFootprints.length, ...added); ctx.commit(changes, "Update Netlist"); }
      // PerformUpdate: each group the update added with a design block link gets the block's layout (Apply Design Block
      // Layout on it alone), and the new footprints are then not handed to Move
      const opts = options();
      if (opts.applyDesignBlockLayouts) {
        const kidOf = (n: SNode, k: string): string => { const c = n.find((x, i) => i > 1 && Array.isArray(x) && x[0] === k) as SNode | undefined; return c ? String(c[1] ?? "") : ""; };
        const linkedGroups = real.added.filter((n) => n[0] === "group" && !!kidOf(n, "lib_id")).map((n) => kidOf(n, "uuid"));
        if (linkedGroups.length) void applyDesignBlockLayoutsToGroups(ctx, linkedGroups);
        newFootprints.splice(0, newFootprints.length);
      }
      report.set(real.report);
      // the netlist's net chains: assignments, terminal pads and the chain classes (after the commit, on the updated nets)
      const shown = real.report.slice();
      void applyNetlistChains(chains).then((warnings) => { if (warnings.length) report.set([...shown, ...warnings.map((text) => ({ severity: "warning" as const, text }))]); });
      plan = null;
      if (okBtn) okBtn.disabled = true;
      return false;                       // KiCad keeps the dialog open with the report; Close dismisses it
    },
    cancel() {
      if (!newFootprints.length || E.viewOnly) return;
      const ids = newFootprints.slice();
      // the selection's reference point is (0,0), where the footprints were spread, so they come to the cursor from there
      window.setTimeout(() => { void import("../tools").then((T) => {
        const m = CollabTools.pcb as unknown as { moveFromReference?(c: unknown, ids: string[], origin: [number, number]): boolean } | undefined;
        if (m && m.moveFromReference) m.moveFromReference(T.toolCtx(), ids, [0, 0]);
        else { (ctx as unknown as { setSelection(ids: string[]): void }).setSelection(ids); T.runModuleAction("move"); }
      }); }, 0);
    } });
  if (!dlg) return;
  okBtn = dlg.okButton; if (okBtn) okBtn.disabled = true;
  const res = await projectNetlist();
  if ("error" in res) { report.set([{ severity: "error", text: res.error }]); return; }
  netlist = res.netlist;
  chains = netlistChainsOf(res.netlist, res.files, res.chainsPath, res.pro);
  await dryRun();
}

// ---------------------------------------------------------------- from the schematic editor (SCH_EDIT_FRAME::OnUpdatePCB)
/**
 * Tools > Update PCB from Schematic… (F8) in the schematic editor: open the project's board (creating it after
 * pcbnew's "PCB '%s' does not exist. Do you wish to create it?" when the project has none), then DIALOG_UPDATE_PCB
 * on it (MAIL_PCB_UPDATE).
 */
export async function updatePcbFromSchematicEditor(ctx: ToolCtx): Promise<void> {
  const { openDoc } = await import("../doc");
  const { toolCtx } = await import("../tools");
  const docs = projectDocs(); const target = NL().projectBoardPath(docs);
  const project = state.project as { projectId?: string } | null;
  const run = async (doc: ProjectDocInfo): Promise<void> => {
    // MAIL_SCH_GET_NETLIST answered by the schematic editor: ReadyToNetlist with its Annotate dialog
    if (!(await schematicReady(true))) return;
    const tabs = (state as { docs?: ProjectDocInfo[] }).docs || [];
    if (!tabs.some((d) => d.docId === doc.docId)) tabs.push(doc);
    await openDoc(doc);
    for (let i = 0; i < 100 && !(E.kdoc && (E.kdoc as KDoc).type === "pcb"); i++) await new Promise((r) => setTimeout(r, 50));
    if (!E.kdoc || (E.kdoc as KDoc).type !== "pcb") { ctx.toast("The board could not be opened"); return; }
    await openUpdatePcb((toolCtx as unknown as () => ToolCtx)());
  };
  if (target.doc) { await run(target.doc); return; }
  if (!target.path || !project || !project.projectId) {
    ctx.toast("Cannot update the PCB because the Schematic Editor is opened in stand-alone mode. In order to create/update PCBs from schematics, launch the main KiCad application and create a project.");
    return;
  }
  if (E.viewOnly) { ctx.toast("View-only access"); return; }
  confirmBox("Confirmation", `PCB '${target.path}' does not exist. Do you wish to create it?`, "OK", () => { void (async () => {
    try {
      const { api } = await import("../util");
      const res = await api(`/api/projects/${project.projectId}/docs`, { method: "POST", body: JSON.stringify({ path: target.path, docType: "kicad_pcb" }) }) as { docId?: string; path?: string; existing?: boolean };
      if (!res || !res.docId) throw new Error("no document id returned");
      const pt = (window as unknown as { PcbTools?: { BOARD_VERSION?: number } }).PcbTools;   // the version the board tools write
      if (!res.existing) await api(`/api/docs/${res.docId}/snapshots?seq=0`, { method: "POST", headers: { "content-type": "text/plain" }, body: NL().newBoardText((pt && pt.BOARD_VERSION) || SEXPR_BOARD_FILE_VERSION) });
      const entry: ProjectDocInfo = { docId: res.docId, path: res.path || target.path, docType: "kicad_pcb" };
      const all = (state.project as { docs?: ProjectDocInfo[] } | null)?.docs; if (all && !all.some((d) => d.docId === entry.docId)) all.push(entry);
      await run(entry);
    } catch (e) { ctx.toast(`Could not create the board: ${(e as Error).message}`); }
  })(); });
}
