// panels/netnav.ts — the schematic Net Navigator (eeschema/net_navigator.cpp, SCH_EDIT_FRAME::RefreshNetNavigator).
//
// With nothing highlighted the root is "Nets" and lists every net of the schematic (unnamed Net-(…) nets too),
// narrowed by the filter box (wildcard by default: a pattern without * or ? matches as a substring).  With a net
// highlighted the root is that net's name and the box is disabled.  Under a net, one node per sheet path that holds
// it ("project/Sub"), and under that the net's pins, sheet pins, labels and no-connects in KiCad's wording ("Symbol
// 'U1' pin '3' (VCC)", "Sheet 'X' pin 'Y'", "Label 'NAME' at (x, y)").  Picking an item changes to its sheet and
// centres on it (onNetNavigatorSelection); a sheet node only changes sheet; a net name does nothing.  A canvas
// highlight selects its item here (SelectNetNavigatorItem).  The nets come from editor/schnets.ts: the whole
// hierarchy, kept as names.
import type { NetNavNode, PanelAction } from "../../panels-api";
import type { schNets } from "../../canvas/sch-nets";
import { HL, clearHighlight, currentInstance, docOfInstance, goTo, netMap, onNetsChanged, setNavStepper } from "../schnets";
import { store } from "../appstore";
import { E } from "../state";
import { isSchDoc, kdoc, loadJson, panelStore, saveJson } from "./core";

interface PropsHelpers { formatLength(mm: number, unit: string): string }
const SN = (): typeof schNets => (KiCadCanvas as unknown as { schNets: typeof schNets }).schNets;
const fmt = (v: number): string => (window.CollabTools.props as unknown as { helpers: PropsHelpers }).helpers.formatLength(v, String(E.units || "mm"));
const unescape = (s: string): string => (KiCadCanvas as unknown as { pcbNetlist: { unescapeNetName(s: string): string } }).pcbNetlist.unescapeNetName(s);

/** The filter text and mode (eeschema settings: net_nav_search_mode_wildcard). */
const filterState = loadJson<{ text: string; wildcard: boolean }>("kc.netnav.filter", { text: "", wildcard: true });
interface NavTarget { inst: number; at: [number, number] | null; item: boolean; id?: string }
const targets = new Map<string, NavTarget>();

function netNode(name: string, collapsed: boolean): NetNavNode {
  const c = netMap(); if (!c) return { key: "net:" + name, label: unescape(name) };
  const sheets = SN().navSheets(c.map, name, c.instances, c.rootName, (inst) => docOfInstance(c, inst), fmt);
  const sel = HL.nav ? `item:${name}|${HL.nav.inst}|${HL.nav.id}|${HL.nav.pin || ""}` : null;
  return {
    key: "net:" + name, label: unescape(name), collapsed,
    children: sheets.map((s) => {
      const sk = `sheet:${name}|${s.inst}`; targets.set(sk, { inst: s.inst, at: null, item: false });
      const items = s.items.map((it) => { const k = `item:${name}|${it.inst}|${it.id}|${it.pin || ""}`; targets.set(k, { inst: it.inst, at: it.at, item: true, id: it.id }); return { key: k, label: it.label, ids: [it.id] }; });
      return { key: sk, label: s.label, children: items, collapsed: !(sel && items.some((i) => i.key === sel)) };
    }),
  };
}

function build(): { root: NetNavNode | null; selected: string | null } {
  targets.clear();
  const doc = kdoc(); if (!doc || !isSchDoc()) return { root: null, selected: null };
  const c = netMap(); if (!c) return { root: null, selected: null };
  if (HL.name) {
    const root = netNode(HL.name, false); root.bold = true;
    const sel = HL.nav ? `item:${HL.name}|${HL.nav.inst}|${HL.nav.id}|${HL.nav.pin || ""}` : null;
    return { root, selected: sel && targets.has(sel) ? sel : null };
  }
  const match = SN().netFilter(filterState.text, filterState.wildcard);
  const names = SN().netNames(c.map).filter((n) => match(unescape(n)));
  // MakeNetNavigatorNode ends with Expand( aParentId ): every net shows its sheets, the sheet nodes stay folded
  return { root: { key: "nets", label: "Nets", bold: true, children: names.map((n) => netNode(n, false)) }, selected: null };
}

const shown = (): boolean => !!((store.get() as { panes?: Record<string, boolean> }).panes || {}).netnav;
// wxEVT_SHOW: a navigator that went stale while hidden rebuilds when it is shown again
let wasShown = false;
store.subscribe(() => { const on = shown(); if (on && !wasShown && stale) setTimeout(publishNetNav, 0); wasShown = on; });
let stale = true, userSel: string | null = null, lastNav: unknown = null;
/** RefreshNetNavigator: rebuilt when shown (a hidden navigator is only marked stale, as KiCad does). */
export function publishNetNav(): void {
  publishNetSheets();
  if (!shown()) { stale = true; return; }
  stale = false;
  let r: { root: NetNavNode | null; selected: string | null } = { root: null, selected: null };
  try { r = build(); } catch (e) { console.warn(e); }
  if (HL.nav !== lastNav) { lastNav = HL.nav; userSel = null; }   // a canvas highlight selects its own node
  const selected = userSel && targets.has(userSel) ? userSel : r.selected;
  const cur = panelStore.get().netNav;
  panelStore.set({ netNav: { root: r.root, version: cur.version + 1, selected, filter: filterState.text, filterEnabled: !HL.name, wildcard: filterState.wildcard } });
}
onNetsChanged(() => publishNetNav());
setNavStepper((dir) => stepNavigator(dir));

/**
 * HIERARCHY_PANE::UpdateNetHighlight: the hierarchy tree paths ("/" root, "/uuid/…/" below) of the sheets that hold the
 * highlighted net (NAVIGATION_QUERY::NetSheets), drawn in LAYER_BRIGHTENED there.
 */
export function netSheetPaths(name: string | null): string[] {
  const c = name ? netMap() : null; if (!c || !name) return [];
  const e = c.map.get(name); if (!e) return [];
  const out = new Set<string>();
  // the net map's uuid paths start with the root sheet's own uuid, which the hierarchy tree leaves out
  const root = c.instances.find((i) => i.human === "/"), skip = root ? root.uuidPath.length : 0;
  for (const m of e.members) {
    const inst = c.instances.find((i) => i.index === m.inst); if (!inst) continue;
    const u = inst.uuidPath.slice(skip); out.add(u.length ? "/" + u.join("/") + "/" : "/");
  }
  return [...out].sort();
}
/** The render settings' LAYER_BRIGHTENED colour, which follows the schematic colour theme. */
const brightened = (): string => (typeof KiCadCanvas !== "undefined" && KiCadCanvas.SCH && KiCadCanvas.SCH.brightened) || "#FF00FF";
function publishNetSheets(): void {
  const marked = netSheetPaths(HL.name || null), markColor = brightened(), h = panelStore.get().hierarchy;
  if ((h.marked || []).join("\n") !== marked.join("\n") || h.markColor !== markColor) panelStore.set({ hierarchy: Object.assign({}, h, { marked, markColor }) });
}
/** What the net navigator and the hierarchy marks follow: the highlighted net, the navigator's item, the theme's brightened colour. */
export function netNavSignature(): string { return (HL.name || "-") + (HL.busMembers ? "+" : "") + (HL.nav ? HL.nav.id + (HL.nav.pin || "") : "") + "|" + brightened(); }

export function netNavDispatch(a: PanelAction): boolean {
  if (a.t === "netNavRefresh") { publishNetNav(); return true; }
  if (a.t === "netNavFind") { findNetByName(a.net); return true; }
  if (a.t === "netNavFilter") {
    if (a.text !== undefined) filterState.text = a.text;
    if (a.wildcard !== undefined) filterState.wildcard = a.wildcard;
    saveJson("kc.netnav.filter", filterState); publishNetNav(); return true;
  }
  if (a.t !== "netNavSelect") return false;
  const key = a.key || "", t = targets.get(key);
  userSel = key || null;
  const cur = panelStore.get().netNav; panelStore.set({ netNav: Object.assign({}, cur, { selected: key || null }) });
  if (!t) return true;                       // the root, or a net name while every net is listed: nothing happens
  void goTo(t.inst, t.item ? t.at : null).then(() => { const now = currentInstance(); if (now && now.index === t.inst) publishNetNav(); });
  return true;
}

/**
 * SCH_EDIT_FRAME::SelectNextPrevNetNavigatorItem (Next / Previous Net Item, Tab / Shift+Tab): from the navigator's
 * selected node to the next leaf of the tree in tree order (the pins, labels, sheet pins and no-connects of the sheets
 * listed), wrapping at both ends.  The tree selection moves with it, which changes sheet and focuses on the item
 * (onNetNavigatorSelection); the item's id comes back for the selection tool, null when there is no selected leaf.
 */
export async function stepNavigator(dir: number): Promise<string | null> {
  let r: { root: NetNavNode | null; selected: string | null } = { root: null, selected: null };
  try { r = build(); } catch (e) { console.warn(e); }
  if (!r.root) return null;
  const leaves: string[] = [];
  const walk = (n: NetNavNode): void => { for (const c of n.children || []) { if ((c.children || []).length) walk(c); else if (targets.get(c.key)?.item) leaves.push(c.key); } };
  walk(r.root);
  const cur = userSel && targets.has(userSel) ? userSel : r.selected;
  const i = cur ? leaves.indexOf(cur) : -1; if (i < 0) return null;
  const key = leaves[((i + (dir >= 0 ? 1 : -1)) % leaves.length + leaves.length) % leaves.length], t = targets.get(key) as NavTarget;
  userSel = key;
  const now = panelStore.get().netNav; panelStore.set({ netNav: Object.assign({}, now, { selected: key }) });
  await goTo(t.inst, t.at);
  const here = currentInstance(); if (here && here.index === t.inst) publishNetNav();
  return here && here.index === t.inst ? t.id || null : null;
}

/**
 * SCH_EDITOR_CONTROL::FindNetInInspector (Find in Net Navigator): the net of the first selected item that is on one,
 * else the highlighted net; SCH_EDIT_FRAME::FindNetInInspector then shows the navigator, clears the highlight and
 * puts the net's name in the filter box.  False when there is no connected net ("No connected net selected.").
 */
export function findNetInNavigator(ids: string[]): boolean {
  const c = netMap(), inst = currentInstance(c); let name = "";
  if (c && inst) for (const id of ids) { const n = c.index.get(inst.index + "|" + id) || ""; if (n && !/^unconnected-/.test(n)) { name = n; break; } }
  if (!name) name = HL.name || "";
  if (!name) return false;
  findNetByName(name);
  return true;
}
/** SCH_EDIT_FRAME::FindNetInInspector( aNetName ): show the navigator, clear the highlight, filter on the name. */
function findNetByName(name: string): void {
  if (!name) return;
  const hk = E.hooks as { showPane?: (name: string, show?: unknown) => void };
  if (!shown() && hk.showPane) hk.showPane("netnav", true);
  filterState.text = unescape(name); saveJson("kc.netnav.filter", filterState);
  userSel = null;
  clearHighlight();
  publishNetNav();
}
